          "definition": "Электронууд давхраануудад хэрхэн байрласныг заасан тоонууд (жишээ: 2, 8, 1).",
          "topicId": "2.1"
        },
        {
          "term": "Атомын радиус",
          "definition": "Цөмөөс гадаад электроны давхраа хүртэлх зай.",
          "topicId": "2.2"
        },
        {
          "term": "Бүлэг",
          "definition": "Үелэх хүснэгтийн босоо багана.",
          "topicId": "2.2"
        },
        {
          "term": "Үе",
          "definition": "Үелэх хүснэгтийн хэвтээ мөр.",
          "topicId": "2.2"
        },
        {
          "term": "Үелэх хандлага",
          "definition": "Үе, бүлгийн дагуу элементийн шинж тодорхой зүй тогтлоор өөрчлөгдөх нь.",
          "topicId": "2.2"
        },
        {
          "term": "Шүлтийн металл",
          "definition": "I бүлгийн металл; устай урвалд орж шүлт ба устөрөгч үүсгэнэ.",
          "topicId": "2.2"
        },
        {
          "term": "Галоген",
          "definition": "VII бүлгийн элемент; «давс төрүүлэгч».",
          "topicId": "2.2"
        },
        {
          "term": "Инерт хий",
          "definition": "VIII бүлгийн, гадаад давхраа нь бүрэн дүүргэгдсэн идэвхгүй хий.",
          "topicId": "2.2"
        },
        {
          "term": "Эртний элемент",
          "definition": "Нээсэн хүн, он нь тодорхойгүй, эрт үеэс мэдэгдэж байсан элемент.",
          "topicId": "2.3"
        },
        {
          "term": "Давс",
          "definition": "Металлын эерэг ион ба сөрөг ионоос тогтсон нэгдэл.",
          "topicId": "1.2"
        },
        {
          "term": "Ион",
          "definition": "Эерэг эсвэл сөрөг цэнэгтэй атом буюу атомын бүлэг.",
          "topicId": "1.2"
        },
        {
          "term": "Эрдэс",
          "definition": "Дэлхийн царцдаст байгалийн аргаар үүссэн тодорхой найрлагатай бодис.",
          "topicId": "1.2"
        },
        {
          "term": "Саармагжих урвал",
          "definition": "Хүчил ба суурь урвалд орж давс ба ус үүсгэх урвал.",
          "topicId": "1.2"
        },
        {
          "term": "Тунадас",
          "definition": "Уусмалд үүсч ёроолд буух уусдаггүй хатуу бодис.",
          "topicId": "1.2"
        },
        {
          "term": "Шүүгдэс",
          "definition": "Шүүлтүүрээр нэвтэрч гарсан тунгалаг шингэн.",
          "topicId": "1.2"
        },
        {
          "term": "Мениск",
          "definition": "Нарийн саван дахь шингэний муруй гадаргуу.",
          "topicId": "1.1"
        },
        {
          "term": "Пипетка",
          "definition": "Тодорхой эзлэхүүнтэй шингэнийг нарийвчлалтай шилжүүлэх багаж.",
          "topicId": "1.1"
        },
        {
          "term": "Бюретка",
          "definition": "Шингэнийг дуслаар нэмж, нэмсэн эзлэхүүнийг нарийвчлалтай уншдаг багаж.",
          "topicId": "1.1"
        },
        {
          "term": "Элементийн идэвх",
          "definition": "Элементийн урвалд орох чадвар.",
          "topicId": "3.1"
        },
        {
          "term": "Халах урвал",
          "definition": "Идэвхтэй элемент нэгдлээс идэвх муутай элементийг халж гаргах урвал.",
          "topicId": "3.1"
        },
        {
          "term": "Идэвхийн эгнээ",
          "definition": "Элементүүдийг халах урвалд орох идэвхээр нь жагсаасан эгнээ.",
          "topicId": "3.1"
        },
        {
          "term": "Термит урвал",
          "definition": "Металлыг оксидоос нь илүү идэвхтэй металлаар (хөнгөнцагаан) халж гаргах, их дулаантай урвал.",
          "topicId": "3.1"
        },
        {
          "term": "Урвалын хурд",
          "definition": "Нэгж хугацаанд урвалж эсвэл бүтээгдэхүүний тоо хэмжээний өөрчлөлт.",
          "topicId": "3.2"
        },
        {
          "term": "Мөргөлдөлтийн онол",
          "definition": "Бөөмс хангалттай энергитэйгээр мөргөлдсөн үед урвал явагдана гэсэн онол.",
          "topicId": "3.2"
        },
        {
          "term": "Катализатор",
          "definition": "Урвалын хурдыг ихэсгэж, урвалын эцэст өөрчлөгдөөгүй үлддэг бодис.",
          "topicId": "3.2"
        },
        {
          "term": "Ингибитор",
          "definition": "Урвалыг удаашруулдаг бодис.",
          "topicId": "3.2"
        },
        {
          "term": "Шатах урвал",
          "definition": "Бодис хүчилтөрөгчтэй урвалд орж гэрэл, дулаан ялгаруулах урвал.",
          "topicId": "3.3"
        },
        {
          "term": "Исэлдэх урвал",
          "definition": "Бодис хүчилтөрөгчтэй нэгдэх урвал.",
          "topicId": "3.3"
        },
        {
          "term": "Экзотерм урвал",
          "definition": "Орчинд дулаан ялгаруулдаг урвал.",
          "topicId": "3.3"
        },
        {
          "term": "Эндотерм урвал",
          "definition": "Орчноос дулаан шингээдэг урвал.",
          "topicId": "3.3"
        },
        {
          "term": "Түлш",
          "definition": "Хүчилтөрөгчид шатаж дулаан ялгаруулдаг бодис.",
          "topicId": "3.3"
        },
        {
          "term": "Таамаглал",
          "definition": "Туршилтаар шалгаж болох, шалтгаантай урьдчилсан тайлбар.",
          "topicId": "4.1"
        },
        {
          "term": "Хяналтын хувьсагч",
          "definition": "Шударга туршилтын тулд тогтмол байлгах хувьсагч.",
          "topicId": "4.1"
        },
        {
          "term": "Тоосонцор (PM)",
          "definition": "Агаарт хөвөх хатуу болон шингэний маш жижиг хэсгүүд; PM10, PM2.5.",
          "topicId": "4.2"
        },
        {
          "term": "Хүлцэх агууламж",
          "definition": "Эрүүл мэндэд сөрөг нөлөөгүй гэж тогтоосон дээд хэмжээ.",
          "topicId": "4.2"
        },
        {
          "term": "Цэвэр үйлдвэрлэл",
          "definition": "Бохирдлыг эх үүсвэр дээр нь бууруулж, нөөцийг үр ашигтай ашиглах арга.",
          "topicId": "4.2"
        },
        {
          "term": "Пестицид",
          "definition": "Таримлыг хортон шавж, хогийн ургамлаас хамгаалах химийн бодис.",
          "topicId": "4.3"
        },
        {
          "term": "Хүнсний нэмэлт",
          "definition": "Хүнсний өнгө, амт, хадгалалтыг сайжруулахаар нэмдэг бодис (Е кодтой).",
          "topicId": "4.3"
        },
        {
          "term": "Хортой бодис",
          "definition": "Эрүүл мэнд, байгальд хор нөлөө үзүүлж, өвчин, үхэлд хүргэж болох бодис.",
          "topicId": "4.3"
        },
        {
          "term": "Аюултай бодис",
          "definition": "Тэсрэмтгий, шатамхай, идэмхий, исэлдүүлэгч, цочроох шинжтэй бодис.",
          "topicId": "4.3"
        }
      ],
      "errata": [
        {
          "topicId": "1.2",
          "noteId": "1.2a",
          "text": "Сурах бичгийн хүснэгт 1.2.1-д нитрат ионыг NO_3^2- гэж бичсэн. Зөв нь **NO_3^-** (−1 цэнэгтэй)."
        },
        {
          "topicId": "1.2",
          "noteId": "1.2c",
          "text": "Сурах бичигт «Цайр + Азотын хүчил → Цайрын нитрат + Устөрөгч» гэж өгсөн. Бодит байдал дээр азотын хүчил металлтай урвалд ороход ихэвчлэн устөрөгч биш азотын оксидууд ялгардаг. 8-р ангийн шалгалтад сурах бичгийн хувилбарыг хүлээн авдаг ч ерөнхий дүрмийн жишээнд хүхрийн эсвэл давсны хүчлийг хэрэглэх нь найдвартай."
        },
        {
          "topicId": "2.1",
          "noteId": "2.1a",
          "text": "Сурах бичгийн х.44-т «устөрөгчийн атомын цөмд нэг протон, нэг электрон» гэж бичсэн. Электрон **цөмд биш**, цөмийг тойрон байрладаг. Устөрөгчийн цөмд ганц протон бий."
        },
        {
          "topicId": "2.1",
          "noteId": "2.1b",
          "text": "Сурах бичигт Резерфорд «ихэнх туяа нэвтрэхгүй гэж таамагласан» мэт бичигдсэн. Томсоны загвар ёсоор эерэг цэнэг атом даяар жигд тархсан тул **бараг бүх** альфа хэсэг бага зэрэг хазайж нэвтрэх ёстой байв. Цөөн хэсэг буцаж ойсон нь гайхшрал төрүүлсэн. Мөн электрон 1896 онд биш, **1897** онд нээгдсэн."
        },
        {
          "topicId": "2.1",
          "noteId": "2.1c",
          "text": "Сурах бичгийн х.52–53-т хлорын массын тоог 36 гэж бичсэн. Түгээмэл изотоп нь **{{nuc:35:17:Cl}}** (18 нейтрон); дундаж харьцангуй атом масс 35.5."
        },
        {
          "topicId": "2.2",
          "noteId": "2.2c",
          "text": "Сурах бичгийн хүснэгт 2.2.2-т бромын хуваарилалтыг 2, 8, 8, 7 гэж бичсэн. Зөв нь **2, 8, 18, 7** (бром эхний 20 элементэд ордоггүй). Хлорын массын тоо 36 биш **35**."
        },
        {
          "topicId": "2.2",
          "noteId": "2.2d",
          "text": "Сурах бичгийн хүснэгт 2.2.3-ын хайлах/буцлах цэгийн утга буруу хуулагдсан (жишээ нь аргоны буцлах цэг 59 °C гэж). Дээрх хүснэгтийн утгууд зөв. Мөн зураг 2.2.10-т гелийг «3 протон» гэж бичсэн, зөв нь **2 протон, 2 нейтрон**."
        },
        {
          "topicId": "2.3",
          "noteId": "2.3a",
          "text": "Сурах бичигт 1868 онд гелийг Рамзай нээсэн мэт бичсэн. 1868 онд **П. Жанссен ба Н. Локьер** нарны гэрлийн спектрээс гелийг илрүүлсэн; дэлхий дээр **Рамзай 1895** онд ялгаж авсан."
        },
        {
          "topicId": "2.3",
          "noteId": "2.3b",
          "text": "Сурах бичгийн х.65-д Менделеевийн таамагласан элементийг «44, 68, 100 дугаар элемент» гэжээ. Эдгээр нь ойролцоо **атом масс**; сканди, галли, германийн дэс дугаар 21, 31, 32."
        },
        {
          "topicId": "3.1",
          "noteId": "3.1a",
          "text": "Сурах бичгийн х.73-т энэ урвалаас «зэсийн сульфатын цэнхэр уусмал» үүснэ гэжээ. Урвалд сульфат оролцоогүй тул үүсэх нь **зэсийн нитрат**."
        },
        {
          "topicId": "3.2",
          "noteId": "3.2c",
          "text": "Сурах бичгийн зураг 3.2.12-т 1 см³ шоог 1000 хэсэгт хуваахад 6000 см² болно гэжээ. Талын урт 0.1 см болох тул нийт талбай = 1000 × 6 × 0.01 = **60 см²** (10 дахин ихсэлт). 8 хэсэгт хуваахад 12 см² (2 дахин) гэдэг нь зөв."
        },
        {
          "topicId": "3.2",
          "noteId": "3.2c",
          "text": "Сурах бичигт катализатор «мөргөлдөлтийн тоог ихэсгэнэ» гэжээ. Илүү зөв тайлбар: мөргөлдөлтийн тоо биш, **ашигтай болох мөргөлдөлтийн хувь** ихэснэ, учир нь бага энерги шаардсан өөр зам бий болно."
        },
        {
          "topicId": "4.3",
          "noteId": "4.3b",
          "text": "Сурах бичигт меламиныг «сүүний өнгийг сайжруулахаар 1 кг-д 2.5 мг хүртэл нэмэхийг зөвшөөрдөг» гэжээ. Меламин хүнсний нэмэлт **биш**; 2.5 мг/кг нь санамсаргүй бохирдлын дээд хязгаар. 2008 онд **уургийн хэмжээг хуурамчаар өсгөх** зорилгоор нэмсэн. Мөн E800–E899 «хөөс намдаагч» гэж бичсэн; хөөс намдаагч нь E900-аар эхэлдэг."
        }
      ],
